Q() { docker exec -i xnova-database psql -U postgres -d postgres -At -c "$1" < /dev/null; }
echo "== fns with planet uuid args"
Q "select p.oid::regprocedure from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and pg_get_function_identity_arguments(p.oid) ~ '(p_planet_id|p_origin_planet_id|p_buyer_planet_id|planet_id) uuid' and p.prorettype <> 'trigger'::regtype and has_function_privilege('authenticated', p.oid, 'EXECUTE') order by 1"
echo "== sync_planet_resources"; Q "select prosrc from pg_proc where proname='sync_planet_resources'"
echo "== recall_deployed_fleet"; Q "select prosrc from pg_proc where proname='recall_deployed_fleet'"
echo "== research_queue cols"; Q "select string_agg(column_name||':'||data_type, ', ' order by ordinal_position) from information_schema.columns where table_schema='public' and table_name='research_queue'"
echo "== _trg_colony_sale_lock_queue"; Q "select prosrc from pg_proc where proname='_trg_colony_sale_lock_queue'"
echo "== _trg_colony_sale_lock fleets"; Q "select tgname, tgfoid::regproc from pg_trigger where tgrelid='public.fleets'::regclass and not tgisinternal"
echo "== admin_revenue check"; Q "select pg_get_constraintdef(oid) from pg_constraint where conrelid='public.admin_revenue'::regclass and contype='c'"
echo "== jackpot contribute src head"; Q "select left(prosrc,1500) from pg_proc where proname='contribute_to_jackpot'"
echo "== record_admin_revenue head"; Q "select left(prosrc,2500) from pg_proc where proname='record_admin_revenue'"
echo "== get_live_tung_price_usd"; Q "select prosrc from pg_proc where proname='get_live_tung_price_usd'"
echo "== planets protect fn"; Q "select tgname||' '||pg_get_triggerdef(oid) from pg_trigger where tgrelid='public.planets'::regclass and not tgisinternal"
echo "== protect_game_table_full"; Q "select prosrc from pg_proc where proname='protect_game_table_full'"
echo "== fleet_ships triggers"; Q "select tgname||' '||pg_get_triggerdef(oid) from pg_trigger where tgrelid in ('public.fleet_ships'::regclass,'public.planet_defenses'::regclass,'public.planet_resources'::regclass,'public.fleets'::regclass) and not tgisinternal"
